<script setup lang="ts">
import { computed,onBeforeUnmount,ref,watch } from 'vue';
import { t,locale } from '../i18n';
import { formatMoney } from '../business-money';
type Group={currency:string;scale:number;gross_atomic:string;active_atomic:string;refunded_atomic:string;transactions:number;days:{date:string;active_atomic:string;gross_atomic:string;transactions:number}[]};
const days=ref('7'),loading=ref(true),error=ref(''),data=ref<{from:string;to:string;currencies:Group[];transactions:number}|null>(null);const currency=ref('');let controller:AbortController|null=null;
const selected=computed(()=>data.value?.currencies.find(g=>g.currency===currency.value)??data.value?.currencies[0]);
const series=computed(()=>{if(!data.value||!selected.value)return [];const points=[];const first=new Date(data.value.from+'T00:00:00Z');const last=new Date(data.value.to+'T00:00:00Z');for(let date=first;date<=last;date=new Date(date.getTime()+86400000)){const day=date.toISOString().slice(0,10);const row=selected.value.days.find(r=>r.date===day);points.push({date:day,atomic:row?.active_atomic??'0'});}return points;});
const max=computed(()=>Math.max(1,...series.value.map(x=>Number(x.atomic))));
const path=computed(()=>series.value.map((v,i)=>`${i===0?'M':'L'} ${45+i*690/Math.max(1,series.value.length-1)} ${230-Number(v.atomic)/max.value*190}`).join(' '));
watch(days,async()=>{controller?.abort();const c=new AbortController();controller=c;loading.value=true;error.value='';const timeout=setTimeout(()=>c.abort(),15000);try{const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});const from=new Date(today+'T00:00:00Z');from.setUTCDate(from.getUTCDate()-Number(days.value)+1);const response=await fetch(`/pos/business/reports/sales-trend?${new URLSearchParams({from:from.toISOString().slice(0,10),to:today})}`,{credentials:'same-origin',redirect:'error',cache:'no-store',headers:{Accept:'application/json'},signal:c.signal});if(!response.ok)throw new Error();const v=await response.json();if(controller!==c)return;data.value=v;currency.value=v.currencies[0]?.currency??'';}catch{if(controller===c)error.value=t('Could not load sales data.');}finally{clearTimeout(timeout);if(controller===c)loading.value=false;}},{immediate:true});
onBeforeUnmount(()=>controller?.abort());
const download=(format:string)=>`/pos/business/reports/sales/download?${new URLSearchParams({format,from:data.value?.from??'',to:data.value?.to??'',locale:locale.value})}`;
</script>
<template><section class="sales-trend merch-panel"><header><div><p class="eyebrow">{{ t('Reports & insights') }}</p><h2>{{ t('Sales trend') }}</h2><p>{{ data?.from }} — {{ data?.to }}</p></div><div><select v-model="days" :aria-label="t('Select period')"><option value="7">{{ t('Last 7 days') }}</option><option value="30">{{ t('Last 30 days') }}</option></select><select v-if="data&&data.currencies.length>1" v-model="currency" :aria-label="t('Currency')"><option v-for="g in data.currencies" :key="g.currency">{{ g.currency }}</option></select></div></header><p v-if="loading" role="status">{{ t('Loading…') }}</p><p v-else-if="error" class="merch-error" role="alert">{{ error }}</p><template v-else-if="selected"><div class="trend-metrics"><article><span>{{ t('Sales before corrections') }}</span><strong>{{ formatMoney(selected.gross_atomic,selected.currency,selected.scale) }}</strong></article><article><span>{{ t('Active sales') }}</span><strong>{{ formatMoney(selected.active_atomic,selected.currency,selected.scale) }}</strong></article><article><span>{{ t('Cash refunded') }}</span><strong>{{ formatMoney(selected.refunded_atomic,selected.currency,selected.scale) }}</strong></article><article><span>{{ t('Transactions') }}</span><strong>{{ selected.transactions }}</strong></article></div><svg viewBox="0 0 770 275" role="img" :aria-label="t('Sales trend')"><g v-for="i in 5" :key="i"><line x1="45" x2="735" :y1="40+(i-1)*47.5" :y2="40+(i-1)*47.5" stroke="#e8edf3"/><text x="30" :y="45+(i-1)*47.5" text-anchor="end" fill="#8da0b2" font-size="9">{{ Math.round((6-i)/5*max/10**selected.scale).toLocaleString(locale==='id'?'id-ID':'en-US') }}</text></g><path :d="`${path} L 735 230 L 45 230 Z`" fill="#e5f4ff"/><path :d="path" fill="none" stroke="#168cd5" stroke-width="2.5"/><g v-for="(point,i) in series" :key="point.date"><circle :cx="45+i*690/Math.max(1,series.length-1)" :cy="230-Number(point.atomic)/max*190" r="3" fill="#168cd5"><title>{{ point.date }} · {{ formatMoney(point.atomic,selected.currency,selected.scale) }}</title></circle><text v-if="i%Math.max(1,Math.floor(series.length/7))===0" :x="45+i*690/Math.max(1,series.length-1)" y="254" text-anchor="middle" fill="#91a2b3" font-size="10">{{ point.date.slice(5) }}</text></g></svg><footer><span>{{ t('Active sales') }} · {{ selected.currency }}</span><div><a :href="download('pdf')">{{ t('Download PDF') }}</a><a :href="download('xlsx')">{{ t('Download Excel') }}</a></div></footer></template><p v-else class="merch-empty">{{ t('No sales in this period.') }}</p></section></template>
<style scoped>.sales-trend{padding:22px;margin:22px 0}.sales-trend header{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.sales-trend h2{font-size:17px;margin:3px 0}.sales-trend p{color:#8294a7;font-size:12px;margin:5px 0}.sales-trend .eyebrow{color:#0783cd;font-size:10px}.sales-trend header>div:last-child{display:flex;gap:8px}.sales-trend select{border:1px solid #dce5ee;background:#fff;padding:7px;border-radius:5px;color:#567187;font-size:12px}.trend-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:25px 0}.trend-metrics article{border-left:3px solid #dceffb;padding-left:12px}.trend-metrics span{display:block;font-size:11px;color:#8397a8}.trend-metrics strong{display:block;margin-top:5px;color:#2a4860;font-size:20px;font-variant-numeric:tabular-nums}.sales-trend svg{width:100%;height:auto;max-height:340px}.sales-trend footer{display:flex;justify-content:space-between;gap:15px;font-size:11px;color:#8b9eae;border-top:1px solid #edf1f5;padding-top:15px}.sales-trend footer>div{display:flex;gap:20px}.sales-trend a{color:#0783cd;text-decoration:none;font-weight:600}@media(max-width:700px){.sales-trend{padding:16px}.trend-metrics{grid-template-columns:1fr 1fr}.trend-metrics strong{font-size:17px}.sales-trend header{flex-direction:column}.sales-trend footer{flex-wrap:wrap}}</style>
